#requires -Version 7.0
param([Parameter(Mandatory=$true)][string]$PackagePath,[switch]$UseLocalAdminVault,[string]$AdminVaultRoot=(Join-Path $env:LOCALAPPDATA 'G6\RabbitMQ\g5-onboarding'))
$ErrorActionPreference='Stop'
$package=[IO.File]::ReadAllBytes([IO.Path]::GetFullPath($PackagePath));if($package.Length -lt 53-or[Text.Encoding]::ASCII.GetString($package,0,5)-ne'G5PK1'){throw 'Invalid encrypted G5 package.'}
$salt=[byte[]]$package[5..20];$iterations=[BitConverter]::ToInt32($package,21);$nonce=[byte[]]$package[25..36];if($iterations-lt 600000-or$iterations-gt 2000000){throw 'Unsupported package KDF parameters.'}
$tagAt=$package.Length-16;$cipher=[byte[]]$package[37..($tagAt-1)];$tag=[byte[]]$package[$tagAt..($package.Length-1)];$aad=[byte[]]$package[0..36]
if($UseLocalAdminVault){$adminVault=Get-Content -Raw -LiteralPath (Join-Path $AdminVaultRoot 'admin-vault.dpapi.json')|ConvertFrom-Json;$member=@($adminVault.members|Where-Object Login -CEQ 'g5_equipo');if($member.Count-ne 1){throw 'The local administrative vault has no unique shared-team package password.'};$secure=ConvertTo-SecureString $member[0].ProtectedPackagePassword}else{$secure=Read-Host 'Contraseña independiente de este paquete' -AsSecureString};$password=[Net.NetworkCredential]::new('', $secure).Password;$derived=[Security.Cryptography.Rfc2898DeriveBytes]::Pbkdf2($password,$salt,$iterations,[Security.Cryptography.HashAlgorithmName]::SHA256,32);$plain=[byte[]]::new($cipher.Length);$aes=[Security.Cryptography.AesGcm]::new($derived,16)
try{$aes.Decrypt($nonce,$cipher,$tag,$plain,$aad)}catch{[Security.Cryptography.CryptographicOperations]::ZeroMemory($plain);throw 'No se pudo autenticar el paquete; contraseña incorrecta o paquete alterado.'}finally{$aes.Dispose()}
$mem=[IO.MemoryStream]::new($plain,$false);$zip=[IO.Compression.ZipArchive]::new($mem,[IO.Compression.ZipArchiveMode]::Read,$false);$files=@{}
try{foreach($e in $zip.Entries){if([string]::IsNullOrWhiteSpace($e.FullName)-or$e.FullName.StartsWith('/')-or$e.FullName-match'(^|/)\.\.(/|$)'-or$e.FullName.Contains('\\')){throw 'Unsafe package path.'};$s=$e.Open();$o=[IO.MemoryStream]::new();$s.CopyTo($o);$s.Dispose();$files[$e.FullName]=$o.ToArray();$o.Dispose()}}finally{$zip.Dispose();$mem.Dispose()}
if(-not$files.ContainsKey('developer.json')-or-not$files.ContainsKey('secrets/credentials.json')-or-not$files.ContainsKey('ssh-config')){throw 'Required G5 package files are missing.'}
$meta=[Text.UTF8Encoding]::new($false,$true).GetString($files['developer.json'])|ConvertFrom-Json;if($meta.Login-notmatch'^g5_[a-z0-9][a-z0-9_-]{1,30}$'-or$meta.SshLogin-cne'g5_tunnel'-or$meta.KeyName-cne'g5_tunnel'-or$meta.SshIdentityShared-ne$true-or$meta.Vhost-ne'g6-productos-ofertas'-or$meta.Port-ne 5673){throw 'Package is not a valid G5 shared-SSH tunnel package.'}
$cred=[Text.UTF8Encoding]::new($false,$true).GetString($files['secrets/credentials.json'])|ConvertFrom-Json;if($cred.username-ne'g5_ventas'-or$cred.vhost-ne'g6-productos-ofertas'-or-not$cred.password){throw 'Invalid G5 RabbitMQ credential payload.'}
$sshDir=Join-Path $env:USERPROFILE '.ssh';$localRoot=Join-Path $env:LOCALAPPDATA "G6\RabbitMQ\$($meta.Login)";$null=New-Item -ItemType Directory -Force -Path $sshDir,$localRoot,(Join-Path $localRoot 'secrets'),(Join-Path $localRoot 'scripts'),(Join-Path $localRoot 'templates');$config=Join-Path $sshDir 'config'
if(Test-Path $config){if(Select-String -LiteralPath $config -Pattern '(?im)^\s*Host\s+g5-dev\s*$'){throw 'Host alias g5-dev already exists; inspect SSH config before installing.'}}
$keyPath=Join-Path $sshDir $meta.KeyName;$expectedPublic=[Text.UTF8Encoding]::new($false,$true).GetString($files['ssh/g5_tunnel.pub']).Trim();$resumePartial=$false;if(Test-Path $keyPath){$existingPublicPath="$keyPath.pub";if(-not(Test-Path $existingPublicPath)-or(Get-Content -Raw -LiteralPath $existingPublicPath).Trim()-cne$expectedPublic){throw 'A different identity already exists at the shared SSH key path; refusing to overwrite.'};$resumePartial=$true};$installedMetadata=Join-Path $localRoot 'developer.json';if((Test-Path $localRoot)-and(Test-Path $installedMetadata)){ $existingMeta=Get-Content -Raw -LiteralPath $installedMetadata|ConvertFrom-Json;if($existingMeta.Login-cne$meta.Login-or$existingMeta.Fingerprint-cne$meta.Fingerprint){throw 'A different G5 installation already exists at the target path.'} }
foreach($name in $files.Keys){if($name-in@('developer.json','ssh-config','secrets/credentials.json','secrets/key-passphrase.txt')){continue};if($name-notmatch'^(scripts|templates|install|ssh)/[A-Za-z0-9._/-]+$'){throw "Unexpected package file $name"};$dest=if($name.StartsWith('ssh/')){Join-Path $sshDir $name.Substring(4)}elseif($name.StartsWith('scripts/')){Join-Path (Join-Path $localRoot 'scripts') $name.Substring(8)}elseif($name.StartsWith('install/')){Join-Path $localRoot $name.Substring(8)}else{Join-Path (Join-Path $localRoot 'templates') $name.Substring(9)};$null=New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest);if($name-eq'ssh/g5_tunnel'-and$resumePartial){continue};[IO.File]::WriteAllBytes($dest,[byte[]]$files[$name])}
$current="$env:USERDOMAIN\$env:USERNAME";$keyPath=Join-Path $sshDir $meta.KeyName;icacls $keyPath /inheritance:r /grant:r "$current`:(F)" 'NT AUTHORITY\SYSTEM:(F)'|Out-Null
$secret=ConvertTo-SecureString -String $cred.password -AsPlainText -Force;Export-Clixml -InputObject $secret -LiteralPath (Join-Path $localRoot 'secrets\g5_ventas.clixml');$secret.Dispose();$keyPass=[Text.UTF8Encoding]::new($false,$true).GetString($files['secrets/key-passphrase.txt'])|ConvertTo-SecureString -AsPlainText -Force;Export-Clixml -InputObject $keyPass -LiteralPath (Join-Path $localRoot 'secrets\key-passphrase.clixml');$keyPass.Dispose()
$meta|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $localRoot 'developer.json') -Encoding utf8;$sshConfig=[Text.UTF8Encoding]::new($false,$true).GetString($files['ssh-config']).Replace('~/.ssh/',([IO.Path]::GetFullPath($sshDir).Replace('\','/')+'/'));if(Test-Path $config){[IO.File]::AppendAllText($config,[Environment]::NewLine+$sshConfig,[Text.UTF8Encoding]::new($false))}else{[IO.File]::WriteAllText($config,$sshConfig,[Text.UTF8Encoding]::new($false))}
icacls $localRoot /inheritance:r /grant:r "$current`:(OI)(CI)F" 'NT AUTHORITY\SYSTEM:(OI)(CI)F' /T /C|Out-Null
Write-Output "Paquete G5 instalado para $($meta.Name). El secreto RabbitMQ quedó protegido por DPAPI en el perfil Windows; usa los scripts locales para túnel y smoke."
foreach($b in $files.Values){[Security.Cryptography.CryptographicOperations]::ZeroMemory([byte[]]$b)};[Security.Cryptography.CryptographicOperations]::ZeroMemory($plain);[Security.Cryptography.CryptographicOperations]::ZeroMemory($derived);[Security.Cryptography.CryptographicOperations]::ZeroMemory($cipher);$password=$null;$cred=$null;$secure.Dispose()
